      "rank": 3,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP converted the cosmic microwave background into a precision quantitative record of the early universe and established a durable cosmological parameter framework.",
        "attribution": "The listed experimental and scientific leaders have identifiable roles, though this was necessarily a broad mission-wide achievement.",
        "maturity": "The measurements have been extensively tested and refined by later CMB observations.",
        "uncertainties": [
          "The boundary between WMAP's distinct achievement and the broader CMB experimental programme needs precise attribution."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "Matthew Colless",
        "Shaun Cole"
      ],
      "assessment": {
        "nobel_worthiness": "Baryon acoustic oscillations furnished a robust standard ruler, allowing the expansion history and dark-energy phenomenology to be tested through large-scale structure.",
        "attribution": "Eisenstein's formulation and the survey teams' detections are identifiable, while Sunyaev's earlier foundational contribution also merits serious consideration.",
        "maturity": "BAO is now a repeatedly measured, central cosmological observable with continuing leverage.",
        "uncertainties": [
          "Credit for prediction, survey design and observational demonstration is distributed across several communities."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Andrew G. Lyne",
        "Marta Burgay",
        "Michael Kramer"
      ],
      "assessment": {
        "nobel_worthiness": "The double pulsar provides one of nature's cleanest strong-field gravity laboratories and enables multiple exceptionally precise tests of general relativity.",
        "attribution": "The discovery and its decisive timing programme can be linked to the listed scientists, with Burgay's discovery role especially clear.",
        "maturity": "Two decades of timing have made the system an enduring and quantitatively powerful test bed.",
        "uncertainties": [
          "The appropriate balance between discovery credit and the broader timing collaboration needs review."
        ]
      }
    },
    {
      "rank": 6,
